337	    /**
338	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
339	     * contained in {@code value}. Reading the digits right to left, every second one is
340	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
341	     * digits are summed, and the check digit is the amount that must be added to that sum to
342	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
343	     * the digit is taken over exactly the digits the string carries.
344	     */
345	    private static int luhnCheckDigit(String value) {
346	        int sum = 0;
347	        boolean doubling = true;
348	        for (int i = value.length() - 1; i >= 0; i--) {
349	            char c = value.charAt(i);
350	            if (c < '0' || c > '9') {
351	                continue;
352	            }
353	            int digit = c - '0';
354	            if (doubling) {
355	                digit *= 2;
356	                if (digit > 9) {
357	                    digit -= 9;
358	                }
359	            }
360	            sum += digit;
361	            doubling = !doubling;
362	        }
363	        return (10 - (sum % 10)) % 10;
364	    }
