366	    /** Fixed city-to-region table used to derive an owner's locality. */
367	    private static final Map<String, String> CITY_REGION = Map.of(
368	        "Sydney", "NSW",
369	        "Melbourne", "VIC",
370	        "Brisbane", "QLD");
371	
372	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
373	    public static final String UNKNOWN_REGION = "UNKNOWN";
374	
