377	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
378	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
379	     * source of the city-to-region mapping, shared by every rule that is keyed by
380	     * region so the mapping is never re-derived elsewhere.
381	     */
382	    public static String regionOf(String city) {
383	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
384	    }
