432	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
433	     * no known range.
434	     */
435	    private static String regionOfPostcode(String postcode) {
436	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
437	            return null;
438	        }
439	        int value = Integer.parseInt(postcode);
440	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
441	            int[] range = entry.getValue();
442	            if (value >= range[0] && value <= range[1]) {
443	                return entry.getKey();
444	            }
445	        }
446	        return null;
447	    }
