449	    /**
450	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
451	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
452	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
453	     */
454	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
455	        "NSW", new int[] {2000, 2099},
456	        "VIC", new int[] {3000, 3099},
457	        "QLD", new int[] {4000, 4099});
458	
459	    /**
460	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
461	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
462	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
463	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
464	     * city with no known region accepts any 4-digit postcode.
465	     */
466	    public boolean isPostcodeValid() {
467	        if (this.postcode == null) {
468	            return true;
469	        }
470	        if (!this.postcode.matches("[0-9]{4}")) {
471	            return false;
472	        }
473	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
474	        if (range == null) {
475	            return true;
476	        }
477	        int value = Integer.parseInt(this.postcode);
478	        return value >= range[0] && value <= range[1];
479	    }
480	
481	    /**
482	     * The national (subscriber) digit count required by each known country calling code, keyed by
483	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
484	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
485	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
486	     * re-derived elsewhere.
487	     */
488	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
489	        "1", 10,
490	        "61", 9);
491	
492	    /**
493	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
494	     * E.164 digit string, choosing the longest matching code known to
495	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
496	     * country code. This is the single place a country code is read from an E.164 number, so every
497	     * rule keyed by that code shares one derivation.
498	     */
499	    private static String countryCodeOf(String e164Digits) {
500	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
501	            .filter(e164Digits::startsWith)
502	            .max(Comparator.comparingInt(String::length))
503	            .orElse(null);
504	    }
505	
506	    /**
507	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
508	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
509	     * known code wins; a number whose country code is not recognised passes this check (its length is
510	     * then governed only by the general E.164 bound), while a recognised code must be followed by
511	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
512	     */
513	    public static boolean hasValidNationalLength(String e164Digits) {
514	        String countryCode = countryCodeOf(e164Digits);
515	        if (countryCode == null) {
516	            return true;
517	        }
518	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
519	    }
520	
521	    /**
522	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
523	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
524	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
525	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
526	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
527	     */
528	    public Integer getMembershipPoints() {
529	        int points = 0;
530	        if (hasEmail()) {
531	            points += 2;
532	        }
533	        if (hasNoNamesakes()) {
534	            points += 1;
535	        }
536	        if (hasLargeHousehold()) {
537	            points += 2;
538	        }
539	        if (hasQualifyingTenure()) {
540	            points += 3;
541	        }
542	        return points;
543	    }
544	
545	    /**
546	     * The owner's membership level, a number from 1 to 4 derived from {@linkplain #getMembershipPoints()
547	     * membershipPoints}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or
548	     * more.
549	     */
550	    public Integer getMembershipLevel() {
551	        int points = getMembershipPoints();
552	        if (points >= 6) {
553	            return 4;
554	        }
555	        if (points >= 4) {
556	            return 3;
557	        }
558	        if (points >= 2) {
559	            return 2;
560	        }
561	        return 1;
562	    }
563	
564	    /**
565	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
566	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
567	     * known, is treated as not a large household.
568	     */
569	    private boolean hasLargeHousehold() {
570	        return this.householdSize != null && this.householdSize >= 3;
571	    }
572	
573	    /**
574	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
575	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
576	     * email presence so the check is never re-derived elsewhere.
577	     */
578	    private boolean hasEmail() {
579	        return this.email != null && !this.email.isEmpty();
580	    }
581	
582	    /**
583	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
584	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
585	     * not known, is treated as not unique.
586	     */
587	    private boolean hasNoNamesakes() {
588	        return this.namesakeCount != null && this.namesakeCount == 0;
589	    }
590	
591	    /**
592	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
593	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
594	     * is crossed only once at least one fiscal-year boundary has passed since registration.
595	     */
596	    private boolean hasQualifyingTenure() {
597	        return this.getTenureFiscalYears() >= 1;
598	    }
599	
600	    /**
601	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
602	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
603	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
604	     * created owner has zero tenure). Never negative.
605	     */
606	    public long getTenureFiscalYears() {
607	        if (this.registrationDate == null) {
608	            return 0;
609	        }
610	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
611	    }
612	
613	    /**
614	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
615	     * otherwise {@code 'PHONE'}.
616	     */
617	    public String getContactPreference() {
618	        return hasEmail() ? "EMAIL" : "PHONE";
619	    }
620	
621	    /**
622	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
623	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
624	     * the national digits grouped into threes from the left separated by spaces,
625	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
626	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
627	     * E.164 form, or carries no known country code.
628	     */
629	    public String getTelephoneDisplay() {
630	        if (this.telephone == null || !this.telephone.startsWith("+")) {
631	            return this.telephone;
632	        }
633	        String digits = this.telephone.substring(1);
634	        String countryCode = countryCodeOf(digits);
635	        if (countryCode == null) {
636	            return this.telephone;
637	        }
638	        String national = digits.substring(countryCode.length());
639	        StringBuilder groups = new StringBuilder();
640	        for (int i = 0; i < national.length(); i += 3) {
641	            if (groups.length() > 0) {
642	                groups.append(' ');
643	            }
644	            groups.append(national, i, Math.min(i + 3, national.length()));
645	        }
646	        return "+" + countryCode + " " + groups;
647	    }
648	
649	    /**
650	     * The owner's identity key: the single derived value used for duplicate detection.
651	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
652	     * empty string when absent) and the householdId (or the empty string when the owner
653	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
654	     * Two owners are duplicates only when their whole identity keys are equal.
655	     */
656	    public String getIdentityKey() {
657	        String telephonePart = this.telephone == null ? "" : this.telephone;
658	        String emailPart = this.email == null ? "" : this.email;
659	        String householdPart = this.householdId == null ? "" : this.householdId;
660	        return telephonePart + "|" + emailPart + "|" + householdPart;
661	    }
662	
663	    protected Set<Pet> getPetsInternal() {
664	        if (this.pets == null) {
665	            this.pets = new HashSet<>();
666	        }
667	        return this.pets;
668	    }
669	
670	    protected void setPetsInternal(Set<Pet> pets) {
671	        this.pets = pets;
672	    }
673	
674	    public List<Pet> getPets() {
675	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
676	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
677	        return Collections.unmodifiableList(sortedPets);
678	    }
679	
680	    public void setPets(List<Pet> pets) {
681	        this.pets = new HashSet<>(pets);
682	    }
683	
684	    public void addPet(Pet pet) {
685	        getPetsInternal().add(pet);
686	        pet.setOwner(this);
687	    }
688	
689	    /**
690	     * Return the Pet with the given name, or null if none found for this Owner.
691	     *
692	     * @param name to test
693	     * @return true if pet name is already in use
694	     */
695	    public Pet getPet(String name) {
696	        return getPet(name, false);
697	    }
698	
699	    /**
700	     * Return the Pet with the given name, or null if none found for this Owner.
701	     *
702	     * @param name to test
703	     * @return true if pet name is already in use
704	     */
705	    public Pet getPet(String name, boolean ignoreNew) {
706	        name = name.toLowerCase();
707	        for (Pet pet : getPetsInternal()) {
708	            if (!ignoreNew || !pet.isNew()) {
709	                String compName = pet.getName();
710	                compName = compName.toLowerCase();
711	                if (compName.equals(name)) {
712	                    return pet;
713	                }
714	            }
715	        }
716	        return null;
717	    }
718	
719	    public Pet getPet(Integer petId) {
720	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
721	    }
722	
723	    @Override
724	    public String toString() {
725	        return new ToStringCreator(this)
726	
727	            .append("id", this.getId())
728	            .append("new", this.isNew())
729	            .append("lastName", this.getLastName())
730	            .append("firstName", this.getFirstName())
731	            .append("address", this.address)
732	            .append("city", this.city)
733	            .append("telephone", this.telephone)
734	            .append("email", this.email)
735	            .toString();
736	    }
737	}
